-- Template store seed for the cannedIQ_dev Supabase project.
-- Generated from PROD template_packs (metadata for all 15 packs).
-- stripe_price_id is intentionally NULLed so dev (Stripe TEST mode) regenerates its own prices.
-- Paid-pack command bodies are NOT included (protected by RLS in prod); only the free pack's
-- commands are seeded. Run in: dev Supabase Dashboard -> SQL Editor.

BEGIN;

ON CONFLICT (id) DO UPDATE SET
  name=EXCLUDED.name, description=EXCLUDED.description, category=EXCLUDED.category,
  icon=EXCLUDED.icon, price_cents=EXCLUDED.price_cents, command_count=EXCLUDED.command_count,
  is_active=EXCLUDED.is_active, is_featured=EXCLUDED.is_featured, preview_text=EXCLUDED.preview_text;

-- Free-pack command bodies (the only commands readable from prod via anon).
ON CONFLICT (id) DO NOTHING;

COMMIT;
