INSERT INTO template_packs
  (id, name, description, category, icon, price_cents, stripe_price_id, command_count, is_active, is_featured, preview_text, created_at)
VALUES
  ('032ba3e5-e7bf-49d5-9670-5166104b63fd', 'Sales Outreach Pro', 'Cold outreach, follow-ups, objection handling, and closing sequences. Built for reps who live in their inbox.', 'sales', '💼', 499, NULL, 10, true, true, 'Hi {{firstName}}, I noticed {{company}} recently...', '2026-06-01T03:58:01.287414+00:00'),
  ('9988e0f2-2e41-4a80-ac8e-9381cb7bf2a1', 'Customer Support Essentials', 'The most common support responses — ticket acknowledgements, escalations, refunds, and follow-ups. Works great in Zendesk, Intercom, and Freshdesk.', 'support', '🎧', 0, NULL, 8, true, true, 'Hi {{firstName}}, thanks for reaching out! I''ve reviewed your case and...', '2026-06-01T03:58:01.287414+00:00'),
  ('d659d1d6-fc14-4fb0-93f4-6244310203f4', 'Medical Billing & Coding', 'Claim denial appeals, patient balance letters, EOB disputes, coding queries, and overpayment refunds. Built for billers, coders, and RCM teams handling insurance every day.', 'healthcare', '🏥', 999, NULL, 10, true, true, 'We are appealing the denial of Claim #{{claimNumber}} citing lack of medical necessity...', '2026-06-05T22:45:28.803827+00:00'),
  ('920e3131-b10e-4618-bdd6-ccac16101b31', 'Recruiting & HR Toolkit', 'Candidate outreach, interview scheduling, offer letters, and rejection messages. Saves hours per week for talent teams.', 'recruiting', '🧑‍💼', 499, NULL, 9, true, false, 'Hi {{firstName}}, your background in {{role}} caught my attention...', '2026-06-01T03:58:01.287414+00:00'),
  ('9b790ae5-b0a5-489d-8397-40913bf146f3', 'Executive Assistant Essentials', 'Meeting requests, follow-up summaries, calendar holds, travel confirmations, and professional declines.', 'general', '📅', 399, NULL, 6, true, false, 'Thank you for reaching out. {{executiveName}} has asked me to...', '2026-06-01T03:58:01.287414+00:00'),
  ('2f52b110-8ae7-4cec-ac82-b19c94b76b03', 'Developer Workflow Pack', 'Code review comments, PR descriptions, bug report templates, standup updates, and on-call handoffs.', 'dev', '💻', 299, NULL, 8, true, false, 'LGTM — left a few inline comments. Main concern is...', '2026-06-01T03:58:01.287414+00:00'),
  ('19a9be20-f9b7-402a-a43f-2a1b15ea1ecc', 'E-commerce Support', 'Order status, shipping delays, returns, refunds, and product FAQs. Optimized for Shopify and WooCommerce stores.', 'support', '🛍️', 299, NULL, 7, true, false, 'I can see your order #{{orderNumber}} shipped on...', '2026-06-01T03:58:01.287414+00:00'),
  ('8f46b986-2daf-40b7-8b42-bcf8efa186ef', 'Higher Education Admissions', 'Inquiry responses, acceptance letters, waitlist notifications, and enrollment nudges. For admissions counselors who need to move fast without losing the personal touch.', 'education', '🎓', 399, NULL, 4, true, false, 'Congratulations! It is my honor to inform you that you have been admitted to {{programName}}...', '2026-06-05T22:45:28.803827+00:00'),
  ('846cde10-f910-4ec9-a368-6ec1dfe91e11', 'Hotel & Hospitality', 'Reservation confirmations, pre-arrival welcome messages, post-stay thank-yous with review requests, and guest complaint responses. For front desk and guest relations teams.', 'hospitality', '🏨', 399, NULL, 4, true, false, 'We''re so excited to welcome you to {{propertyName}} — your stay is just {{daysUntilArrival}} away!', '2026-06-05T22:45:28.803827+00:00'),
  ('9c4fcfe4-992d-4336-bff1-f91a0bcdbfa1', 'Prior Authorization', 'Outpatient auth requests, expedited reviews, peer-to-peer requests, denial appeals, and patient notifications. Covers every stage of the prior auth lifecycle.', 'healthcare', '📋', 799, NULL, 6, true, false, 'This is a request for EXPEDITED authorization review for {{serviceName}} (CPT: {{cptCode}})...', '2026-06-05T22:45:28.803827+00:00'),
  ('a8596ae0-680d-4a2b-8df2-a30047cceabd', 'Revenue Cycle Management', 'AR follow-ups, payer escalations, credentialing status requests, denial trend alerts, patient payment plans, and RCM team huddle agendas.', 'healthcare', '💰', 799, NULL, 6, true, false, 'This claim has been outstanding for {{daysPending}} days. We request immediate escalation...', '2026-06-05T22:45:28.803827+00:00'),
  ('af43c34d-e785-4f11-b3dc-597e6e46b97e', 'Physician Practice Communications', 'Referral letters, lab result notifications, care gap outreach, appointment reminders, no-show follow-ups, prescription denials, and hospital discharge notifications to PCPs.', 'healthcare', '👨‍⚕️', 699, NULL, 8, true, false, 'I am referring my patient {{patientName}} for evaluation of {{referralReason}}...', '2026-06-05T22:45:28.803827+00:00'),
  ('475e0776-6008-4efd-aa7a-0d4879ecef8e', 'Law Firm Client Communications', 'Engagement letters, matter status updates, demand letters, settlement summaries, and contract renewal reminders. Clean, professional, and attorney-ready.', 'legal', '⚖️', 699, NULL, 5, true, false, 'This letter confirms the terms of our engagement in connection with {{matterDescription}}...', '2026-06-05T22:45:28.803827+00:00'),
  ('4fc0a18c-baf7-41d5-8a42-fe7f1e53da9a', 'Real Estate Agent', 'Offer cover letters, inspection follow-ups, price reduction recommendations, closing day checklists, and post-closing check-ins. For buyer and listing agents.', 'realestate', '🏡', 499, NULL, 5, true, false, 'On behalf of my clients {{buyerNames}}, I am pleased to present this offer on {{propertyAddress}}...', '2026-06-05T22:45:28.803827+00:00'),
  ('fc406489-9716-4c11-82be-86ebfa8eed54', 'Accounts Receivable & Collections', 'Professional invoices, 7-day friendly reminders, 30-day overdue follow-ups, payment plan offers, and final demand letters before collections.', 'finance', '📊', 499, NULL, 5, true, false, 'Invoice #{{invoiceNumber}} for {{invoiceAmount}} is due on {{dueDate}}...', '2026-06-05T22:45:28.803827+00:00')
INSERT INTO template_commands (id, pack_id, command_data, sort_order)
VALUES
  ('40fe7200-954f-41ee-abfa-ff9542ca42c2', '9988e0f2-2e41-4a80-ac8e-9381cb7bf2a1', '{"name": "Ticket Acknowledgement", "actions": [{"type": "insert_text"}], "template": "Hi {{firstName}},\n\nThank you for reaching out to cannedIQ Support! I\u2019ve received your request and want you to know we\u2019re on it.\n\nI\u2019ll be reviewing your case and will follow up within {{responseTime}} business hours with an update.\n\nIn the meantime, if you have any additional details to share, please reply to this message.\n\nBest,\n{{agentName}}", "triggers": [{"type": "slash", "value": "/ack"}], "variables": [{"name": "firstName", "type": "text", "label": "Customer first name"}, {"name": "responseTime", "type": "text", "label": "Response time (hours)", "defaultValue": "4"}, {"name": "agentName", "type": "text", "label": "Your name"}], "commandType": "variable", "description": "First response to a new support ticket"}'::jsonb, 1),
  ('8345583a-e4eb-434e-9104-48ed8bc2d2a7', '9988e0f2-2e41-4a80-ac8e-9381cb7bf2a1', '{"name": "Refund Approved", "actions": [{"type": "insert_text"}], "template": "Hi {{firstName}},\n\nGreat news! Your refund of {{amount}} has been approved and processed.\n\nYou should see the funds returned to your {{paymentMethod}} within 3\u20135 business days, depending on your bank.\n\nIf you don\u2019t see it by {{expectedDate}}, please don\u2019t hesitate to reach back out.\n\nWe appreciate your patience and hope to serve you again!\n\n{{agentName}}", "triggers": [{"type": "slash", "value": "/refund-ok"}], "variables": [{"name": "firstName", "type": "text", "label": "Customer first name"}, {"name": "amount", "type": "text", "label": "Refund amount (e.g. $49.00)"}, {"name": "paymentMethod", "type": "select", "label": "Payment method", "options": ["credit card", "debit card", "PayPal", "bank account"]}, {"name": "expectedDate", "type": "text", "label": "Expected by date"}, {"name": "agentName", "type": "text", "label": "Your name"}], "commandType": "variable", "description": "Notify customer their refund has been approved"}'::jsonb, 2),
  ('1c6d5333-b293-4cf3-9274-344099927ce9', '9988e0f2-2e41-4a80-ac8e-9381cb7bf2a1', '{"name": "Escalation Notice", "actions": [{"type": "insert_text"}], "template": "Hi {{firstName}},\n\nI wanted to update you that your case has been escalated to our {{teamName}} team who specialize in {{issueType}}.\n\nA specialist will be in touch within {{timeframe}}. Your case reference is {{caseId}}.\n\nThank you for your patience.\n\n{{agentName}}", "triggers": [{"type": "slash", "value": "/escalate"}], "variables": [{"name": "firstName", "type": "text", "label": "Customer first name"}, {"name": "teamName", "type": "text", "label": "Team name (e.g. Technical)"}, {"name": "issueType", "type": "text", "label": "Issue type"}, {"name": "timeframe", "type": "text", "label": "Response timeframe", "defaultValue": "24 hours"}, {"name": "caseId", "type": "text", "label": "Case/ticket ID"}, {"name": "agentName", "type": "text", "label": "Your name"}], "commandType": "variable", "description": "Let customer know their case has been escalated"}'::jsonb, 3),
  ('db547035-fde4-4ba9-a699-b6514cf04b8e', '9988e0f2-2e41-4a80-ac8e-9381cb7bf2a1', '{"name": "Issue Resolved \u2014 Closing", "actions": [{"type": "insert_text"}], "template": "Hi {{firstName}},\n\nI\u2019m glad we were able to resolve {{issue}} for you!\n\nIf you have any other questions or run into anything else, don\u2019t hesitate to reach out. We\u2019re always happy to help.\n\nHave a great {{dayPart}}!\n\n{{agentName}}", "triggers": [{"type": "slash", "value": "/close-ok"}], "variables": [{"name": "firstName", "type": "text", "label": "Customer first name"}, {"name": "issue", "type": "text", "label": "Issue summary"}, {"name": "dayPart", "type": "select", "label": "Time of day", "options": ["day", "weekend", "week"]}, {"name": "agentName", "type": "text", "label": "Your name"}], "commandType": "variable", "description": "Close a resolved ticket professionally"}'::jsonb, 4),
  ('cfc854dd-cbf1-401d-a5d4-935f640552d6', '9988e0f2-2e41-4a80-ac8e-9381cb7bf2a1', '{"name": "Need More Information", "actions": [{"type": "insert_text"}], "template": "Hi {{firstName}},\n\nThank you for contacting us! To help you as quickly as possible, I need a bit more information:\n\n{{questions}}\n\nOnce I have these details, I\u2019ll be able to get this sorted out for you right away.\n\nLooking forward to hearing from you!\n\n{{agentName}}", "triggers": [{"type": "slash", "value": "/need-info"}], "variables": [{"name": "firstName", "type": "text", "label": "Customer first name"}, {"name": "questions", "type": "text", "label": "Questions (one per line)"}, {"name": "agentName", "type": "text", "label": "Your name"}], "commandType": "variable", "description": "Ask for clarification before proceeding"}'::jsonb, 5),
  ('3725ab10-c374-4887-a686-fc5416938740', '9988e0f2-2e41-4a80-ac8e-9381cb7bf2a1', '{"name": "Shipping Delay Apology", "actions": [{"type": "insert_text"}], "template": "Hi {{firstName}},\n\nI\u2019m reaching out to let you know that your order (#{{orderNumber}}) is experiencing a slight delay due to {{reason}}.\n\nYour updated estimated delivery date is {{newDate}}. I sincerely apologize for any inconvenience this causes.\n\nAs a thank-you for your patience, {{compensation}}.\n\nIf you have any questions, I\u2019m here to help.\n\n{{agentName}}", "triggers": [{"type": "slash", "value": "/ship-delay"}], "variables": [{"name": "firstName", "type": "text", "label": "Customer first name"}, {"name": "orderNumber", "type": "text", "label": "Order number"}, {"name": "reason", "type": "text", "label": "Delay reason", "defaultValue": "high demand"}, {"name": "newDate", "type": "text", "label": "New estimated delivery"}, {"name": "compensation", "type": "text", "label": "Compensation offer (or leave blank)", "defaultValue": "we\u2019ve added a 10% discount to your account"}, {"name": "agentName", "type": "text", "label": "Your name"}], "commandType": "variable", "description": "Proactively communicate a shipping delay"}'::jsonb, 6),
  ('cda4145c-2c35-40ee-ba25-513733cfa29f', '9988e0f2-2e41-4a80-ac8e-9381cb7bf2a1', '{"name": "Subscription Cancellation", "actions": [{"type": "insert_text"}], "template": "Hi {{firstName}},\n\nI\u2019ve processed your cancellation request for {{productName}}. Your subscription is now cancelled and you won\u2019t be charged again.\n\nYou\u2019ll continue to have access until {{endDate}}.\n\nIf you ever decide to come back, we\u2019d love to have you. Is there anything we could have done better? Your feedback means a lot to us.\n\n{{agentName}}", "triggers": [{"type": "slash", "value": "/cancel-ack"}], "variables": [{"name": "firstName", "type": "text", "label": "Customer first name"}, {"name": "productName", "type": "text", "label": "Product/plan name", "defaultValue": "cannedIQ Pro"}, {"name": "endDate", "type": "text", "label": "Access end date"}, {"name": "agentName", "type": "text", "label": "Your name"}], "commandType": "variable", "description": "Acknowledge a subscription cancellation gracefully"}'::jsonb, 7),
  ('3f5f1dae-ed81-4931-bbd7-48a87ad8de3d', '9988e0f2-2e41-4a80-ac8e-9381cb7bf2a1', '{"name": "Follow-Up Check-In", "actions": [{"type": "insert_text"}], "template": "Hi {{firstName}},\n\nI wanted to follow up and make sure everything is still working well after we resolved {{issue}} last week.\n\nIs there anything else I can help you with?\n\n{{agentName}}", "triggers": [{"type": "slash", "value": "/follow-up"}], "variables": [{"name": "firstName", "type": "text", "label": "Customer first name"}, {"name": "issue", "type": "text", "label": "Issue that was resolved"}, {"name": "agentName", "type": "text", "label": "Your name"}], "commandType": "variable", "description": "Follow up after a resolved issue"}'::jsonb, 8)
